∀ {F : Type u_2} {n m c t : ℕ}
  {color : PCP.Algebraic.ThreeColorVerifier.Vertex F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 3 → ZMod 2}
  {validCert :
    PCP.Algebraic.ThreeColorVerifier.PairPoint F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1 → ZMod 2}
  {difference :
    PCP.Algebraic.ThreeColorVerifier.PairPoint F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 3 → ZMod 2}
  {properCert :
    PCP.Algebraic.ThreeColorVerifier.ProperPoint F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1 → ZMod 2}
  {colorLines : PCP.Algebraic.EncodedLineLowDegreeTest.Auxiliary F (Fin n) m c t}
  {validLines differenceLines : PCP.Algebraic.EncodedLineLowDegreeTest.Auxiliary F (Fin n ⊕ Fin n) m c t}
  {properLines : PCP.Algebraic.EncodedLineLowDegreeTest.Auxiliary F (Fin (n + n) ⊕ Fin (n + n)) m c t}
  {color_1 :
    PCP.Algebraic.ThreeColorVerifier.Vertex F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 3 → ZMod 2}
  {validCert_1 :
    PCP.Algebraic.ThreeColorVerifier.PairPoint F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1 → ZMod 2}
  {difference_1 :
    PCP.Algebraic.ThreeColorVerifier.PairPoint F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 3 → ZMod 2}
  {properCert_1 :
    PCP.Algebraic.ThreeColorVerifier.ProperPoint F n → PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1 → ZMod 2}
  {colorLines_1 : PCP.Algebraic.EncodedLineLowDegreeTest.Auxiliary F (Fin n) m c t}
  {validLines_1 differenceLines_1 : PCP.Algebraic.EncodedLineLowDegreeTest.Auxiliary F (Fin n ⊕ Fin n) m c t}
  {properLines_1 : PCP.Algebraic.EncodedLineLowDegreeTest.Auxiliary F (Fin (n + n) ⊕ Fin (n + n)) m c t},
  { color := color, validCert := validCert, difference := difference, properCert := properCert,
        colorLines := colorLines, validLines := validLines, differenceLines := differenceLines,
        properLines := properLines } =
      { color := color_1, validCert := validCert_1, difference := difference_1, properCert := properCert_1,
        colorLines := colorLines_1, validLines := validLines_1, differenceLines := differenceLines_1,
        properLines := properLines_1 } →
    color = color_1 ∧
      validCert = validCert_1 ∧
        difference = difference_1 ∧
          properCert = properCert_1 ∧
            colorLines = colorLines_1 ∧
              validLines = validLines_1 ∧ differenceLines = differenceLines_1 ∧ properLines = properLines_1

∀ {F : Type u_2} {n m c t : ℕ} {a : PCP.Algebraic.ThreeColorVerifier.ProperPoint F n}
  {a_1 : PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1} {a_2 : PCP.Algebraic.ThreeColorVerifier.ProperPoint F n}
  {a_3 : PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1},
  PCP.Algebraic.ThreeColorVerifier.Query.properCert a a_1 = PCP.Algebraic.ThreeColorVerifier.Query.properCert a_2 a_3 →
    a = a_2 ∧ a_1 = a_3

∀ {F : Type u_2} {n m c t : ℕ} {a : PCP.Algebraic.ThreeColorVerifier.PairPoint F n}
  {a_1 : PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 3} {a_2 : PCP.Algebraic.ThreeColorVerifier.PairPoint F n}
  {a_3 : PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 3},
  PCP.Algebraic.ThreeColorVerifier.Query.difference a a_1 = PCP.Algebraic.ThreeColorVerifier.Query.difference a_2 a_3 →
    a = a_2 ∧ a_1 = a_3

∀ {P : (List Bool → List Bool → Bool) → Prop} {L : PCP.Language} {witnessBound : Polynomial ℕ}
  {check : List Bool → List Bool → Bool} {check_polyTime : P check}
  {spec : ∀ (x : List Bool), L x ↔ ∃ w, w.length ≤ Polynomial.eval x.length witnessBound ∧ check x w = true}
  {witnessBound_1 : Polynomial ℕ} {check_1 : List Bool → List Bool → Bool} {check_polyTime_1 : P check_1}
  {spec_1 : ∀ (x : List Bool), L x ↔ ∃ w, w.length ≤ Polynomial.eval x.length witnessBound_1 ∧ check_1 x w = true},
  { witnessBound := witnessBound, check := check, check_polyTime := check_polyTime, spec := spec } =
      { witnessBound := witnessBound_1, check := check_1, check_polyTime := check_polyTime_1, spec := spec_1 } →
    witnessBound = witnessBound_1 ∧ check = check_1

∀ {F : Type u_2} {n m c t : ℕ}
  {a : PCP.Algebraic.ThreeColorVerifier.ProperPoint F n × PCP.Algebraic.ThreeColorVerifier.ProperPoint F n}
  {a_1 : PCP.Algebraic.BinaryLocalCorrection.InnerPoint F m c}
  {a_2 : PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1}
  {a_3 : PCP.Algebraic.ThreeColorVerifier.ProperPoint F n × PCP.Algebraic.ThreeColorVerifier.ProperPoint F n}
  {a_4 : PCP.Algebraic.BinaryLocalCorrection.InnerPoint F m c}
  {a_5 : PCP.Algebraic.BinaryPolynomialSpace.Coefficients t 1},
  PCP.Algebraic.ThreeColorVerifier.Query.properLine a a_1 a_2 =
      PCP.Algebraic.ThreeColorVerifier.Query.properLine a_3 a_4 a_5 →
    a = a_3 ∧ a_1 = a_4 ∧ a_2 = a_5

